using System.Security.Cryptography;
using System.Text;
using Microsoft.EntityFrameworkCore;
using Quizymode.Api.Data;
using Quizymode.Api.Shared.Models;
using Quizymode.Api.Shared.Taxonomy;

namespace Quizymode.Api.Services.Taxonomy;

/// <summary>
/// Upserts parsed taxonomy definitions into Categories, Keywords and KeywordRelations. It writes the same rows as the
/// SQL generated by <c>tools/Quizymode.TaxonomySqlGen</c> (a test compares the two), but takes only data, so admin seed
/// sync never executes SQL read from the source repository. Nothing is deleted. The caller owns the transaction.
/// </summary>
internal static class TaxonomyDatabaseSync
{
    private const string SeederUser = "seeder";
    private const string OtherSlug = "other";
    private const string OtherDescription = "Items not in a specific subcategory.";
    private static readonly DateTime SeedTimestampUtc = new(2024, 1, 1, 0, 0, 0, DateTimeKind.Utc);

    public static async Task ApplyAsync(
        ApplicationDbContext db,
        IReadOnlyDictionary<string, TaxonomyCategoryDefinition> definitions,
        CancellationToken cancellationToken)
    {
        Dictionary<string, Category> categories = await UpsertCategoriesAsync(db, definitions, cancellationToken);
        Dictionary<string, Keyword> keywords = await UpsertKeywordsAsync(db, definitions, cancellationToken);
        await db.SaveChangesAsync(cancellationToken);

        await UpsertRelationsAsync(db, definitions, categories, keywords, cancellationToken);
        await db.SaveChangesAsync(cancellationToken);
    }

    private static async Task<Dictionary<string, Category>> UpsertCategoriesAsync(
        ApplicationDbContext db,
        IReadOnlyDictionary<string, TaxonomyCategoryDefinition> definitions,
        CancellationToken cancellationToken)
    {
        List<string> names = definitions.Keys.ToList();
        Dictionary<string, Category> categories = await db.Categories
            .Where(category => names.Contains(category.Name))
            .ToDictionaryAsync(category => category.Name, StringComparer.Ordinal, cancellationToken);

        foreach (string name in names.Order(StringComparer.Ordinal))
        {
            string description = definitions[name].Description;
            if (!categories.TryGetValue(name, out Category? category))
            {
                category = new Category
                {
                    Id = DeterministicGuid($"taxonomy:category:{name}"),
                    Name = name,
                    IsPrivate = false,
                    CreatedBy = SeederUser,
                    CreatedAt = SeedTimestampUtc
                };
                db.Categories.Add(category);
                categories[name] = category;
            }

            category.Description = Truncate(description, 500);
            category.ShortDescription = ShortDescription(description);
        }

        return categories;
    }

    private static async Task<Dictionary<string, Keyword>> UpsertKeywordsAsync(
        ApplicationDbContext db,
        IReadOnlyDictionary<string, TaxonomyCategoryDefinition> definitions,
        CancellationToken cancellationToken)
    {
        List<string> names = definitions.Values
            .SelectMany(definition => definition.AllKeywordSlugs)
            .Append(OtherSlug)
            .Select(name => Truncate(name, 30))
            .Distinct(StringComparer.Ordinal)
            .Order(StringComparer.Ordinal)
            .ToList();

        Dictionary<string, Keyword> keywords = await db.Keywords
            .Where(keyword => !keyword.IsPrivate && keyword.CreatedBy == SeederUser && names.Contains(keyword.Name))
            .ToDictionaryAsync(keyword => keyword.Name, StringComparer.Ordinal, cancellationToken);

        foreach (string name in names)
        {
            string slug = TaxonomyKeywordSlug.FromName(name);
            slug = Truncate(string.IsNullOrEmpty(slug) ? name : slug, 30);

            if (keywords.TryGetValue(name, out Keyword? existing))
            {
                existing.Slug ??= slug;
                continue;
            }

            Keyword keyword = new()
            {
                Id = DeterministicGuid($"taxonomy:keyword:public:{SeederUser}:{name}"),
                Name = name,
                Slug = slug,
                IsPrivate = false,
                CreatedBy = SeederUser,
                CreatedAt = SeedTimestampUtc,
                IsReviewPending = false
            };
            db.Keywords.Add(keyword);
            keywords[name] = keyword;
        }

        return keywords;
    }

    private static async Task UpsertRelationsAsync(
        ApplicationDbContext db,
        IReadOnlyDictionary<string, TaxonomyCategoryDefinition> definitions,
        Dictionary<string, Category> categories,
        Dictionary<string, Keyword> keywords,
        CancellationToken cancellationToken)
    {
        // Later entries win for a repeated path, as with consecutive upserts.
        Dictionary<(Guid CategoryId, Guid? ParentId, Guid ChildId), (int SortOrder, string? Description)> wanted = [];

        foreach (string categoryName in definitions.Keys.Order(StringComparer.Ordinal))
        {
            Guid categoryId = categories[categoryName].Id;

            if (keywords.TryGetValue(OtherSlug, out Keyword? other))
            {
                wanted[(categoryId, null, other.Id)] = (0, OtherDescription);
            }

            IReadOnlyList<TaxonomyL1Group> groups = definitions[categoryName].L1Groups;
            for (int i = 0; i < groups.Count; i++)
            {
                if (!keywords.TryGetValue(groups[i].Slug, out Keyword? parent))
                {
                    continue;
                }

                wanted[(categoryId, null, parent.Id)] = (i + 1, RelationDescription(groups[i].Description));

                IReadOnlyList<TaxonomyL2Leaf> leaves = groups[i].L2Leaves;
                for (int j = 0; j < leaves.Count; j++)
                {
                    if (keywords.TryGetValue(leaves[j].Slug, out Keyword? child))
                    {
                        wanted[(categoryId, parent.Id, child.Id)] = (j, RelationDescription(leaves[j].Description));
                    }
                }
            }
        }

        List<Guid> categoryIds = categories.Values.Select(category => category.Id).ToList();
        List<KeywordRelation> stored = await db.KeywordRelations
            .Where(relation => categoryIds.Contains(relation.CategoryId))
            .ToListAsync(cancellationToken);
        ILookup<(Guid, Guid?, Guid), KeywordRelation> existing =
            stored.ToLookup(relation => (relation.CategoryId, relation.ParentKeywordId, relation.ChildKeywordId));

        foreach (KeyValuePair<(Guid CategoryId, Guid? ParentId, Guid ChildId), (int SortOrder, string? Description)> entry in wanted)
        {
            List<KeywordRelation> relations = existing[entry.Key].ToList();
            if (relations.Count == 0)
            {
                KeywordRelation relation = new()
                {
                    Id = Guid.NewGuid(),
                    CategoryId = entry.Key.CategoryId,
                    ParentKeywordId = entry.Key.ParentId,
                    ChildKeywordId = entry.Key.ChildId,
                    IsPrivate = false,
                    IsReviewPending = false,
                    CreatedAt = SeedTimestampUtc
                };
                db.KeywordRelations.Add(relation);
                relations.Add(relation);
            }

            foreach (KeywordRelation relation in relations)
            {
                relation.SortOrder = entry.Value.SortOrder;
                relation.Description = entry.Value.Description;
            }
        }
    }

    private static string? RelationDescription(string description) =>
        string.IsNullOrWhiteSpace(description) ? null : Truncate(description, 500);

    private static string ShortDescription(string description) =>
        Truncate(string.Join(' ', description.Split(' ', StringSplitOptions.RemoveEmptyEntries).Take(5)), 120);

    private static string Truncate(string value, int max) => value.Length <= max ? value : value[..max];

    /// <summary>The ids the generated seed SQL uses, so both paths create the same rows.</summary>
    private static Guid DeterministicGuid(string input)
    {
        byte[] hash = SHA256.HashData(Encoding.UTF8.GetBytes(input));
        Span<byte> bytes = stackalloc byte[16];
        hash.AsSpan(0, 16).CopyTo(bytes);
        bytes[6] = (byte)((bytes[6] & 0x0F) | 0x40);
        bytes[8] = (byte)((bytes[8] & 0x3F) | 0x80);
        return new Guid(bytes);
    }
}
